/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 findOrLoadStreamSlot(M2C_UNK);                         /* extern */
M2C_UNK loadMeshFrame(M2C_UNK *, s32, M2C_UNK, M2C_UNK); /* extern */
M2C_UNK computeBonePositions(s32, M2C_UNK *, M2C_UNK, M2C_UNK); /* extern */

/* Loads a mesh animation frame into a temporary buffer and computes its bone positions using stream slot 0x11. */ void getMeshFrameBonePositions(s32 meshId, M2C_UNK frameIndex, M2C_UNK outPositions, M2C_UNK outParam) {
    u8 meshFrame[0x628];

    loadMeshFrame(meshFrame, meshId, frameIndex, 0);
    computeBonePositions(findOrLoadStreamSlot(0x11), meshFrame, outPositions, outParam);
}
